import sys; sys.path.insert(0, '/workspace/derm-teach/website/tools/v4/authoring'); from enr import *

E('dress',
  kf=["**DRESS** is a severe, delayed drug reaction: rash, fever, **facial oedema**, lymphadenopathy, eosinophilia and organ involvement.",
      "Latency **2–8 weeks**; culprits: allopurinol, carbamazepine and other aromatic anticonvulsants, lamotrigine, sulfonamides/dapsone, minocycline, vancomycin.",
      "The liver is the commonest organ involved; also kidney, lung, heart, thyroid. Mortality about 2–10%.",
      "Stop the drug and arrange **same-day hospital assessment**; systemic steroids tapered slowly over 6–12 weeks.",
      "Follow up thyroid function and glucose for 1–2 years (late autoimmunity)."],
  epi=[{"t": "**Who**", "sub": ["About 1 in 1,000 to 1 in 10,000 exposures to high-risk drugs; adults more than children.", "HLA risk alleles: HLA-B*58:01 (allopurinol), HLA-A*31:01 (carbamazepine in Europeans)."]}],
  myths=["**\"It's just a drug rash\"**: facial swelling, fever and abnormal blood tests mean a systemic emergency."],
  patho_lead="DRESS combines a **drug-specific T-cell attack** with **herpesvirus reactivation**.",
  mech=[("Drug presentation", "The drug or a metabolite binds HLA molecules and activates T cells (often in genetically susceptible people)."),
        ("Th2 and eosinophils", "IL-5 and other Th2 cytokines drive eosinophilia and tissue infiltration."),
        ("Viral reactivation", "HHV-6, then EBV and CMV reactivate, sustaining inflammation and relapses."),
        ("Organ damage", "Infiltrating T cells and eosinophils injure the liver, kidney, lung and heart."),
        ("Late autoimmunity", "Immune dysregulation after recovery can cause thyroiditis or type 1 diabetes.")],
  histo=["Interface or spongiotic dermatitis with dense perivascular lymphocytes and eosinophils; not specific. RegiSCAR scoring combines clinical and lab features."],
  special=[{"t": "**Allopurinol in CKD**", "sub": ["Highest risk with recent start, high dose, renal impairment and HLA-B*58:01 (common in Han Chinese, Thai and Korean people)."]}],
  comp=["Fulminant hepatitis, interstitial nephritis, pneumonitis, myocarditis; death.", "Autoimmune thyroiditis, type 1 diabetes, alopecia areata after recovery."],
  prog=["Recovery over weeks to months; relapses during steroid taper are common."],
  see_also=["agep", "morbilliform-drug-eruption", "drug-induced-blistering", "drug-eruption-approach"])

E('agep',
  kf=["**AGEP** is a pustular drug reaction: hundreds of tiny **non-follicular** sterile pustules on red, swollen skin, with fever.",
      "Starts in the flexures and face **within hours to 2 days** of an antibiotic (aminopenicillins, macrolides) or other drug (hydroxychloroquine, diltiazem, terbinafine).",
      "Neutrophilia is common; organ involvement is mild and uncommon.",
      "Stop the drug, potent topical steroid and supportive care; settles in **1–2 weeks** with peeling.",
      "Main differential: generalised pustular psoriasis (history of psoriasis, slower course)."],
  epi=[{"t": "**Who**", "sub": ["Rare (about 1–5 per million per year); any age; more women."]}],
  myths=["**\"Pustules mean infection\"**: AGEP pustules are sterile; more antibiotics can make it worse."],
  patho_lead="Drug-specific T cells summon **neutrophils** into the top of the epidermis.",
  mech=[("T-cell activation", "Drug-specific CD4+ and CD8+ T cells migrate into the epidermis."),
        ("IL-8 release", "T cells and keratinocytes release **IL-8 (CXCL8)** and IL-17."),
        ("Subcorneal pustules", "Neutrophils gather just under the stratum corneum, forming pinhead pustules.", "v4-agep-subcorneal.jpg", "AGEP: neutrophil-filled pustules collect just under the stratum corneum (subcorneal), not around hair follicles, over swollen inflamed skin."),
        ("Desquamation", "As pustules dry, the surface peels in collarettes over 1–2 weeks.")],
  histo=["Subcorneal or intraepidermal spongiform pustules, papillary oedema, eosinophils, sometimes necrotic keratinocytes."],
  comp=["Superinfection; rarely liver, kidney or lung involvement; fluid loss in frail patients."],
  prog=["Excellent once the drug is stopped; recurs on re-exposure."],
  see_also=["dress", "palmoplantar-pustulosis", "psoriasis", "drug-eruption-approach", "folliculitis"])

E('infantile-haemangioma',
  kf=["**Infantile haemangioma** is the commonest tumour of infancy (about 4–10% of infants): absent or faint at birth, then rapid growth.",
      "Most growth happens in the **first 1–3 months**; involution over years, often leaving fibrofatty tissue or telangiectasia.",
      "High-risk sites: **periocular, airway/beard, lip, nasal tip, large segmental facial, perineal**, ulcerated, or 5 or more lesions.",
      "Refer high-risk lesions early, ideally by about **4 weeks** of age; **propranolol** is first-line and specialist-initiated.",
      "Five or more skin haemangiomas: liver ultrasound. Large facial segmental lesions: think PHACE."],
  epi=[{"t": "**Who**", "sub": ["More in girls, premature and low-birth-weight babies, and twins.", "Head and neck in about 60%."]}],
  myths=["**\"Wait and it will go away\"**: most do, but high-risk ones need treatment in the early growth window."],
  patho_lead="A haemangioma is a **benign proliferation of immature endothelial cells** that later switches off.",
  mech=[("Trigger", "Tissue hypoxia (possibly placental) induces HIF-1α and VEGF in a progenitor cell population."),
        ("Proliferation", "GLUT-1–positive endothelial cells proliferate rapidly in the first months."),
        ("Plateau", "Growth slows by about 5 months."),
        ("Involution", "Endothelial cells undergo apoptosis and are replaced by fibrofatty tissue over years.", "haemangioma-natural-history.jpg", "Natural history: appearance, rapid growth, slow involution."),
        ("Propranolol effect", "Beta-blockade causes vasoconstriction, reduces VEGF signalling and speeds involution.")],
  histo=["Lobules of capillaries lined by GLUT-1–positive endothelium (GLUT-1 negative in congenital haemangiomas and malformations)."],
  special=[{"t": "**PHACE syndrome**", "sub": ["Posterior fossa anomalies, Haemangioma (large facial segmental), Arterial, Cardiac (coarctation) and Eye anomalies: needs MRI/MRA, echo and eye review."]},
           {"t": "**LUMBAR syndrome**", "sub": ["Lumbosacral segmental haemangioma with spinal and urogenital anomalies: spinal imaging."]}],
  comp=["Ulceration (painful, scarring), bleeding, amblyopia, airway obstruction, feeding problems, disfigurement; heart failure with large liver haemangiomas."],
  prog=["Most involute; residual skin changes are common in large or deep lesions."],
  see_also=["port-wine-stain", "pyogenic-granuloma", "pigmented-birthmarks", "neonatal-rashes"])

E('port-wine-stain',
  kf=["**Port-wine stain** is a capillary **malformation**, present at birth, that grows with the child and never involutes.",
      "Caused by a **somatic GNAQ** mutation; about 0.3% of newborns.",
      "Darkens and thickens with age (cobblestoning, overgrowth).",
      "Facial **V1** distribution: assess for **Sturge–Weber** (glaucoma, seizures); limb stain with overgrowth: consider Klippel–Trénaunay.",
      "**Pulsed dye laser** (specialist) lightens it, best started early; camouflage for all."],
  epi=[{"t": "**Who**", "sub": ["Equal sexes; any site, face commonest."]}],
  myths=["**\"It's a stork mark that will fade\"**: salmon patches fade; port-wine stains do not."],
  patho_lead="A port-wine stain is a patch of **malformed, progressively widening capillaries**.",
  mech=[("Mosaic mutation", "A GNAQ mutation in a developing cell gives a patch of abnormal vessels."),
        ("Ectatic capillaries", "Dermal capillaries are dilated and increase in calibre with age.", "v4-pws-capillaries.jpg", "Normal fine dermal capillaries (left) versus the widened, crowded capillaries of a port-wine stain (right)."),
        ("Reduced neural control", "Poor sympathetic innervation of the vessels allows progressive dilation."),
        ("Thickening", "Over decades vessels enlarge further, causing darker colour, blebs and soft-tissue overgrowth.")],
  histo=["Dilated capillaries and venules in the papillary and reticular dermis without endothelial proliferation."],
  special=[{"t": "**Sturge–Weber syndrome**", "sub": ["V1 facial PWS with leptomeningeal angiomatosis and glaucoma: seizures, hemiparesis, learning difficulties."]}],
  comp=["Glaucoma, seizures (Sturge–Weber); limb overgrowth; bleeding from blebs; psychosocial impact."],
  prog=["Permanent; laser lightens but rarely clears."],
  see_also=["infantile-haemangioma", "pigmented-birthmarks", "neonatal-rashes", "intense-pulsed-light"])

E('arterial-leg-ulcer',
  kf=["**Arterial ulcers** are caused by **peripheral arterial disease** and account for about 10–20% of leg ulcers (alone or mixed).",
      "Punched-out, deep, painful ulcers on the toes, heel, lateral malleolus or shin; cold, hairless foot with weak pulses.",
      "Pain worse on elevation and at night, eased by hanging the leg down.",
      "Measure ABPI (toe pressures in diabetes); **never compress** an ischaemic limb.",
      "Urgent vascular referral; same day for critical limb ischaemia. Stop smoking; antiplatelet and statin."],
  epi=[{"t": "**Who**", "sub": ["Older smokers, people with diabetes, CKD, hypertension and hyperlipidaemia."]}],
  myths=["**\"All leg ulcers need compression\"**: compression can cause gangrene in arterial disease."],
  patho_lead="Too little arterial blood reaches the skin, so it **dies from ischaemia**.",
  mech=[("Atherosclerosis", "Plaques narrow the arteries of the leg."),
        ("Reduced perfusion", "Distal skin receives too little oxygen, especially at pressure points and on elevation."),
        ("Necrosis", "Minor trauma causes tissue death that cannot heal: a punched-out ulcer."),
        ("Critical ischaemia", "Rest pain, gangrene and tissue loss signal limb-threatening disease.")],
  histo=["Not used; diagnosis is clinical and vascular (ABPI, duplex, angiography)."],
  special=[{"t": "**Mixed ulcers**", "sub": ["ABPI 0.5–0.8: reduced compression only under specialist guidance; below 0.5: no compression, urgent vascular."]}],
  comp=["Infection, gangrene, amputation; high cardiovascular mortality."],
  prog=["Healing depends on revascularisation."],
  see_also=["diabetic-foot-ulcer", "venous-leg-ulcer", "pyoderma-gangrenosum", "red-leg"])

E('diabetic-foot-ulcer',
  kf=["**Neuropathic (diabetic foot) ulcers** form on insensate pressure points: plantar metatarsal heads, heel and toe tips.",
      "Painless, surrounded by **callus**, with warm feet and good pulses unless neuro-ischaemic.",
      "Test with a **10 g monofilament**; probe to bone and X-ray/MRI for osteomyelitis.",
      "Any diabetic foot ulcer: refer to the multidisciplinary foot service **within 1 working day** (NICE NG19).",
      "Same-day admission for spreading infection, sepsis, crepitus, wet gangrene or suspected Charcot foot."],
  epi=[{"t": "**Who**", "sub": ["Up to a quarter of people with diabetes develop a foot ulcer in their lifetime; most amputations in diabetes follow an ulcer."]}],
  myths=["**\"It doesn't hurt, so it's not serious\"**: absence of pain is the problem."],
  patho_lead="Without **protective sensation**, repeated pressure goes unnoticed and breaks down the skin.",
  mech=[("Neuropathy", "Sensory loss removes pain warning; motor neuropathy causes clawing and abnormal pressure; autonomic neuropathy dries and cracks skin."),
        ("Callus", "High plantar pressure builds thick callus, which raises pressure further."),
        ("Ulceration", "Tissue breaks down beneath the callus and the ulcer deepens towards bone.", "v4-dfu-pressure.jpg", "Neuropathic plantar ulcer: callus over a deep ulcer above the metatarsal head, with damaged nerve fibres and concentrated pressure."),
        ("Infection and ischaemia", "Poor perfusion and impaired immunity let infection spread to bone (osteomyelitis).")],
  histo=["Bone biopsy or deep tissue samples guide treatment of osteomyelitis."],
  special=[{"t": "**Charcot foot**", "sub": ["Hot, swollen, red foot in neuropathy, often painless: immobilise and refer the same day."]}],
  comp=["Osteomyelitis, sepsis, amputation; high mortality."],
  prog=["Many heal with offloading; recurrence is common, so lifelong foot protection is needed."],
  see_also=["arterial-leg-ulcer", "venous-leg-ulcer", "cellulitis-erysipelas", "leprosy"])

E('acne-scars',
  kf=["**Atrophic acne scars** follow collagen loss after inflammatory acne: **ice-pick**, **boxcar** and **rolling**.",
      "Ice-pick scars are the commonest (about 60–70%).",
      "Separate true scars from **post-inflammatory hyperpigmentation or erythema** (flat colour change, which fades).",
      "Prevention matters most: treat acne early; scarring is a referral trigger under NICE NG198.",
      "Treatments (TCA CROSS, subcision, lasers, microneedling) are specialist or cosmetic; aim for improvement, not removal."],
  epi=[{"t": "**Who**", "sub": ["Some scarring affects many people with moderate to severe acne; risk rises with delayed treatment and picking."]}],
  myths=["**\"Scars will fade completely\"**: atrophic scars are permanent; colour marks fade."],
  patho_lead="Deep inflammation **destroys collagen** faster than it can be rebuilt.",
  mech=[("Deep inflammation", "Ruptured follicles release contents into the dermis, causing intense inflammation."),
        ("Collagen destruction", "Enzymes (MMPs) break down dermal collagen."),
        ("Imperfect repair", "Healing lays down too little collagen, leaving a depression.", "v3-atrophic-scar-types.jpg", "Atrophic scar types: ice-pick, boxcar and rolling."),
        ("Tethering", "Fibrous bands pull the surface down in rolling scars (released by subcision).")],
  special=[{"t": "**Skin of colour**", "sub": ["PIH is very common and often more distressing than scars; higher procedure risk."]}],
  comp=["Psychological distress, low self-esteem, depression."],
  prog=["Permanent but improvable with combined treatment."],
  see_also=["acne-vulgaris", "keloids-hypertrophic-scars", "cosmetic-procedures", "retinoids"])

E('keloids-hypertrophic-scars',
  kf=["**Hypertrophic scars** stay within the wound and often settle; **keloids** extend beyond it, persist and recur.",
      "Keloids are much commoner in skin of colour and families; sites: earlobes, jawline, chest, shoulders, upper back.",
      "First line: **silicone gel or sheet** for months; pressure; potent topical steroid under occlusion.",
      "Specialist: intralesional steroid, cryotherapy, laser, excision with adjuvant therapy.",
      "Biopsy an atypical or rapidly growing 'keloid' to exclude DFSP."],
  epi=[{"t": "**Who**", "sub": ["Keloids peak at 10–30 years; up to 15–20× more common in people of African descent."]}],
  myths=["**\"Cut it out and it's gone\"**: keloids recur in most cases after simple excision."],
  patho_lead="Raised scars come from **too much collagen** and not enough breakdown.",
  mech=[("Wound", "Injury starts normal healing: inflammation, proliferation, remodelling."),
        ("Overactive fibroblasts", "TGF-β signalling keeps fibroblasts producing collagen."),
        ("Hypertrophic vs keloid", "Hypertrophic scars stay in the wound; keloids invade surrounding skin with thick, glassy collagen.", "v3-hypertrophic-vs-keloid.jpg", "Hypertrophic scar (left) within the wound; keloid (right) extends beyond it."),
        ("Tension", "Wounds under tension (chest, shoulders) are most prone.")],
  histo=["Keloid: thick hyalinised (glassy) collagen bundles; hypertrophic scar: nodules of collagen parallel to the surface."],
  comp=["Itch, pain, restricted movement, disfigurement."],
  prog=["Hypertrophic scars often improve over 1–2 years; keloids persist."],
  see_also=["acne-scars", "dermatofibroma", "dermatofibrosarcoma-protuberans", "skin-surgery-consent-complications"])

E('intense-pulsed-light',
  kf=["**IPL** uses filtered broad-spectrum flashlamp light to target **melanin** (lentigines, hair) and **haemoglobin** (redness, telangiectasia).",
      "Usually 3–6 sessions; treated pigment darkens ('coffee grounds') then flakes over 1–2 weeks.",
      "Risks: burns, blistering, hypo- or hyperpigmentation, scarring, eye injury; highest in tanned or darker skin.",
      "Never treat undiagnosed pigmented lesions; caution with photosensitising drugs, recent isotretinoin, HSV.",
      "Melasma is a poor candidate; cosmetic and not NHS-funded."],
  myths=["**\"IPL is a laser\"**: it is non-coherent broad-spectrum light, less selective than lasers."],
  patho_lead="IPL heats **coloured targets** in the skin, which absorb the light more than their surroundings.",
  mech=[("Light absorption", "Melanin and oxyhaemoglobin absorb specific wavelengths."),
        ("Selective heating", "Short pulses heat the target faster than heat spreads (selective photothermolysis)."),
        ("Clearance", "Damaged pigment is shed; heated vessels collapse and are reabsorbed."),
        ("Collateral risk", "Epidermal melanin also absorbs energy, so tanned or darker skin burns more easily.")],
  comp=["Burns, pigment change (grid pattern), scarring, eye injury, paradoxical hair growth."],
  prog=["Results fade with new sun damage; maintenance sessions are common."],
  see_also=["solar-lentigines", "photoageing", "rosacea", "cosmetic-procedures", "eyelash-enhancement"])

E('eyelash-enhancement',
  kf=["**Bimatoprost** is a prostamide (glaucoma drug) that lengthens, thickens and darkens eyelashes when applied to the upper lid margin.",
      "Works by **prolonging anagen**; results build over weeks to months and reverse on stopping.",
      "Warn about **permanent iris darkening** (hazel/green eyes), reversible eyelid pigmentation, irritation and redness.",
      "Exclude a disease cause of lash loss (alopecia areata, thyroid disease, blepharitis, trichotillomania).",
      "Cosmetic serums vary in content; prescription products need proper counselling."],
  myths=["**\"Natural serums are safer\"**: many contain undeclared prostaglandin analogues."],
  patho_lead="Bimatoprost acts on **prostamide receptors** in the lash follicle to keep it growing.",
  mech=[("Receptor binding", "Bimatoprost binds prostamide/FP receptors in the dermal papilla."),
        ("Longer anagen", "Follicles stay in the growth phase longer and more follicles enter anagen."),
        ("Thicker, darker lashes", "Follicle size and melanogenesis increase."),
        ("Melanocyte side effects", "Iris and eyelid melanocytes increase pigment production.")],
  comp=["Iris pigmentation (permanent), periocular pigmentation, conjunctival hyperaemia, periorbital fat atrophy."],
  prog=["Lashes return to baseline within weeks to months after stopping."],
  see_also=["alopecia-areata", "trichotillomania", "intense-pulsed-light", "cosmetic-procedures"])

E('halo-naevus',
  kf=["A **halo naevus** is a mole with a symmetrical white ring caused by immune destruction of melanocytes.",
      "Common in children and teenagers (about 1%); often on the back; may be multiple.",
      "Associated with **vitiligo**; the centre may disappear and the ring later repigment.",
      "Reassure if the central naevus is regular; sun-protect the white skin.",
      "Refer a **new halo in an adult over 40** or any atypical centre (melanoma can provoke halos)."],
  myths=["**\"The ring means cancer\"**: in young people it is a sign of benign immune clearance."],
  patho_lead="The immune system **clears the naevus** and the melanocytes around it.",
  mech=[("Immune recognition", "CD8+ T cells recognise antigens on naevus melanocytes."),
        ("Destruction", "Naevus cells and surrounding normal melanocytes are destroyed, creating the white halo.", "v3-halo-blue-spitz.jpg", "Halo naevus (white ring), blue naevus and Spitz naevus."),
        ("Regression", "The central naevus fades and may vanish."),
        ("Repigmentation", "Melanocytes repopulate the ring over months to years in many.")],
  histo=["Naevus with a dense lymphocytic infiltrate; loss of melanocytes in the halo."],
  comp=["Sunburn of the white ring; association with vitiligo."],
  prog=["Benign; often regresses fully."],
  see_also=["melanocytic-naevi", "blue-naevus", "spitz-naevus", "melanoma", "hypopigmentation-skin-of-colour"])

E('blue-naevus',
  kf=["A **blue naevus** is a benign collection of **dermal melanocytes**: a steel-blue, firm, dome-shaped papule.",
      "Blue because deep pigment scatters back blue light (**Tyndall effect**).",
      "Head and neck, backs of hands and feet, buttocks; usually under 1 cm.",
      "Reassure if long-standing and stable; dermoscopy shows homogeneous blue pigment.",
      "Refer new, enlarging or large (>1 cm) lesions in adults: nodular or metastatic melanoma can look blue."],
  myths=["**\"Blue moles are bruises or tattoos\"**: a persisting blue papule without trauma is often a blue naevus, but must be stable."],
  patho_lead="Melanocytes that **stopped in the dermis** during development produce pigment deep in the skin.",
  mech=[("Arrested migration", "Melanocytes travelling from the neural crest to the epidermis stop in the dermis."),
        ("GNAQ/GNA11 mutation", "A mutation drives a small clonal proliferation."),
        ("Tyndall effect", "Deep pigment scatters blue light back to the eye.", "v3-tyndall-blue.jpg", "Deep dermal pigment looks blue (Tyndall effect); superficial pigment looks brown.")],
  histo=["Dendritic, heavily pigmented melanocytes and melanophages in the dermis; cellular blue naevus has nodules of spindle cells."],
  comp=["Rarely, malignant blue naevus (melanoma arising in a blue naevus)."],
  prog=["Stable for life in almost all."],
  see_also=["melanocytic-naevi", "halo-naevus", "spitz-naevus", "melanoma", "pigmented-birthmarks"])

E('spitz-naevus',
  kf=["**Spitz naevi** are benign naevi of large epithelioid/spindle melanocytes that **grow quickly in children**.",
      "Pink-red or pigmented dome; dermoscopy starburst pattern or dotted vessels. **Reed naevus**: dark symmetrical starburst, often thigh of young women.",
      "They can be clinically and histologically hard to tell from melanoma (spitzoid melanoma).",
      "Children under 12 with typical lesions may be monitored by specialists; **adolescents and adults: excision**.",
      "Atypical Spitz tumours need specialist histopathology review."],
  epi=[{"t": "**Who**", "sub": ["Mostly children and young adults; face and limbs."]}],
  myths=["**\"Fast growth always means melanoma\"**: in young children it is typical of Spitz naevi, but needs specialist assessment."],
  patho_lead="Spitz naevi grow from a **single driver event** (HRAS mutation or kinase fusion), then stop.",
  mech=[("Driver", "An HRAS mutation or a kinase fusion (ALK, ROS1, NTRK, BRAF, MET) starts growth."),
        ("Rapid growth", "Large epithelioid and spindle melanocytes proliferate over months."),
        ("Stabilisation", "Senescence halts growth; many involute or become fibrotic over years."),
        ("Spectrum", "Additional mutations push lesions towards atypical Spitz tumour and spitzoid melanoma.")],
  histo=["Symmetrical, well-circumscribed proliferation of large epithelioid/spindle melanocytes with Kamino bodies; maturation with depth."],
  comp=["Diagnostic uncertainty; rarely malignant behaviour (atypical Spitz tumour)."],
  prog=["Benign in most children; may regress."],
  see_also=["melanocytic-naevi", "halo-naevus", "blue-naevus", "melanoma", "pyogenic-granuloma"])

E('perioral-dermatitis',
  kf=["**Perioral dermatitis** is a facial eruption of tiny papules and pustules around the mouth, nose or eyes with **sparing next to the lips**.",
      "Commonest in women aged 20–45 and children; often provoked by **topical, inhaled or nasal steroids** and heavy creams.",
      "No comedones (unlike acne); no flushing (unlike rosacea).",
      "Stop steroids and cosmetics, expect a rebound; topical metronidazole or azelaic acid; oral tetracycline for 6–8 weeks if needed.",
      "Children under 12: erythromycin rather than tetracycline."],
  epi=[{"t": "**Who**", "sub": ["Women 20–45 most; prepubertal children (often periocular, steroid-related)."]}],
  aet=["Steroids disrupt the barrier and the follicle; occlusive cosmetics; possibly fluorinated toothpaste and microbiome changes."],
  myths=["**\"Hydrocortisone will settle it\"**: it masks it briefly and then makes it worse."],
  patho_lead="Steroids and occlusion damage the **barrier around facial follicles**, triggering inflammation.",
  mech=[("Barrier disruption", "Steroids and heavy creams thin the barrier and alter the follicular microbiome."),
        ("Follicular inflammation", "Innate immune activation causes small papules and pustules around follicles."),
        ("Steroid dependence", "Steroids suppress the rash; stopping causes rebound, so patients reapply.", "v3-perioral-face.jpg", "Perioral dermatitis: papules around the mouth and nose, with a clear rim next to the lips."),
        ("Resolution", "Stopping the trigger and anti-inflammatory treatment restores the barrier over weeks.")],
  histo=["Rarely needed: perifollicular lymphohistiocytic infiltrate; granulomatous in the granulomatous variant."],
  special=[{"t": "**Granulomatous periorificial dermatitis**", "sub": ["Yellow-brown papules in children of African descent; slower to clear; refer if persistent."]}],
  comp=["Steroid dependence, rebound flares, distress."],
  prog=["Clears over 6–12 weeks with treatment; recurs if steroids are restarted."],
  see_also=["rosacea", "acne-mimics", "acne-vulgaris", "topical-corticosteroids", "contact-dermatitis"])
